/**
 * The personal action plan.
 *
 * Diabetes outcomes are driven mostly by things that are not a prescription:
 * when you eat, how much of the plate is rice, whether you walk after dinner,
 * whether the evening dose is actually taken, and whether anyone is watching
 * the trend. This turns a patient's own 14-day record into a small number of
 * specific, checkable actions.
 *
 * It is generated by RULES, not by the model, for the same reason triage is:
 * the advice must be the same every time for the same data, inspectable, and
 * incapable of inventing a drug. The model is used only to phrase the plan
 * warmly in Urdu — and it may not add to it.
 *
 * Nothing here selects a medicine or changes a dose.
 */

import type { Features } from '../memory/engine.ts';
import type { ProfileFact } from '../memory/engine.ts';

export type PlanCategory = 'movement' | 'food' | 'medicine' | 'monitoring' | 'feet' | 'doctor';

export interface PlanAction {
  category: PlanCategory;
  /** Why this action is here, in the patient's own numbers. */
  becauseEn: string;
  becauseUr: string;
  doEn: string;
  doUr: string;
  /** Higher runs first. */
  weight: number;
}

const fact = (facts: ProfileFact[], k: string) => facts.find((f) => f.key === k)?.value;

/**
 * Food names are stored in English (the extractor normalises them so they can
 * be matched across turns), but an Urdu plan is read aloud by an Urdu voice —
 * Latin letters come out as English noise. Transliterate what we know.
 */
const FOOD_UR: Record<string, string> = {
  biryani: 'بریانی', raita: 'رائتہ', roti: 'روٹی', naan: 'نان', paratha: 'پراٹھا',
  rice: 'چاول', chawal: 'چاول', pulao: 'پلاؤ', daal: 'دال', sabzi: 'سبزی',
  chana: 'چنے', chai: 'چائے', tea: 'چائے', lassi: 'لسی', samosa: 'سموسہ',
  pakora: 'پکوڑا', nihari: 'نہاری', haleem: 'حلیم', korma: 'قورمہ', kebab: 'کباب',
  mithai: 'مٹھائی', halwa: 'حلوہ', jalebi: 'جلیبی', barfi: 'برفی', kheer: 'کھیر',
  fruit: 'پھل', mango: 'آم', banana: 'کیلا', dates: 'کھجور', potato: 'آلو',
  egg: 'انڈہ', milk: 'دودھ', yoghurt: 'دہی', curd: 'دہی', juice: 'جوس',
};

const foodUr = (f: string) => FOOD_UR[f.trim().toLowerCase()] ?? f;

/**
 * Build the plan. Deterministic: the same features always produce the same
 * actions in the same order.
 */
export function buildPlan(features: Features, facts: ProfileFact[]): PlanAction[] {
  const out: PlanAction[] = [];
  const f = features;

  // ── Rising morning readings ─────────────────────────────────────────
  if (f.risingFastingDays >= 3 || f.dawnPhenomenon) {
    out.push({
      category: 'food',
      weight: 95,
      becauseEn: f.risingFastingDays >= 3
        ? `Your fasting sugar has risen ${f.risingFastingDays} mornings in a row.`
        : 'Your fasting readings are consistently high.',
      becauseUr: f.risingFastingDays >= 3
        ? `آپ کی صبح کی شوگر ${f.risingFastingDays} دن سے مسلسل بڑھ رہی ہے۔`
        : 'آپ کی خالی پیٹ شوگر مسلسل زیادہ آ رہی ہے۔',
      doEn: 'Eat dinner before 8 pm and keep it light — one roti with daal or sabzi rather than rice.',
      doUr: 'رات کا کھانا آٹھ بجے سے پہلے اور ہلکا کھائیں — چاول کی بجائے ایک روٹی دال یا سبزی کے ساتھ۔',
    });
    out.push({
      category: 'movement',
      weight: 90,
      becauseEn: 'A walk after the evening meal lowers the next morning\'s reading.',
      becauseUr: 'رات کے کھانے کے بعد چہل قدمی اگلی صبح کی شوگر کم کرتی ہے۔',
      doEn: 'Walk for 15 minutes after dinner, every night this week.',
      doUr: 'اس ہفتے روزانہ رات کے کھانے کے بعد پندرہ منٹ چہل قدمی کریں۔',
    });
  }

  // ── Post-meal spikes, named against the actual foods ────────────────
  if (f.postMealSpikes7 > 0) {
    const foods = f.spikeFoods.slice(0, 2);
    const foodsEn = foods.length ? foods.join(' and ') : 'rice and heavy meals';
    const foodsUr = foods.length ? foods.map(foodUr).join(' اور ') : 'چاول اور بھاری کھانے';
    out.push({
      category: 'food',
      weight: 88,
      becauseEn: `You had ${f.postMealSpikes7} reading${f.postMealSpikes7 > 1 ? 's' : ''} above 200 after eating this week${foods.length ? `, most often after ${foodsEn}` : ''}.`,
      becauseUr: `اس ہفتے کھانے کے بعد ${f.postMealSpikes7} بار شوگر دو سو سے اوپر گئی${foods.length ? `، زیادہ تر ${foodsUr} کے بعد` : ''}۔`,
      doEn: `Halve the portion of ${foodsEn}, fill the rest of the plate with salad and sabzi, and eat the vegetables first.`,
      doUr: `${foodsUr} کی مقدار آدھی کریں، باقی پلیٹ سلاد اور سبزی سے بھریں، اور پہلے سبزی کھائیں۔`,
    });
    out.push({
      category: 'movement',
      weight: 80,
      becauseEn: 'Walking within 30 minutes of a meal blunts the rise more than walking later.',
      becauseUr: 'کھانے کے آدھے گھنٹے کے اندر چہل قدمی شوگر کے اضافے کو زیادہ کم کرتی ہے۔',
      doEn: 'Walk 20 minutes after your largest meal of the day.',
      doUr: 'دن کے سب سے بڑے کھانے کے بعد بیس منٹ چہل قدمی کریں۔',
    });
  }

  // ── Adherence ───────────────────────────────────────────────────────
  if (f.missedDoses7 >= 1) {
    out.push({
      category: 'medicine',
      weight: 92,
      becauseEn: `You missed ${f.missedDoses7} dose${f.missedDoses7 > 1 ? 's' : ''} in the last week — usually the evening one.`,
      becauseUr: `پچھلے ہفتے آپ سے ${f.missedDoses7} خوراک رہ گئی — اکثر رات والی۔`,
      doEn: 'Set a phone alarm for your evening dose, and keep the tablets where you eat dinner rather than in a cupboard.',
      doUr: 'رات کی دوا کے لیے فون میں الارم لگائیں، اور گولیاں الماری کی بجائے وہیں رکھیں جہاں آپ رات کا کھانا کھاتے ہیں۔',
    });
  } else if (f.adherenceStreakDays >= 3) {
    out.push({
      category: 'medicine',
      weight: 40,
      becauseEn: `You have taken every dose on time for ${f.adherenceStreakDays} days.`,
      becauseUr: `آپ ${f.adherenceStreakDays} دن سے ہر خوراک وقت پر لے رہی ہیں۔`,
      doEn: 'Keep doing exactly this — it is the single biggest thing in your control.',
      doUr: 'بالکل ایسے ہی جاری رکھیں — یہ آپ کے اختیار میں سب سے بڑی چیز ہے۔',
    });
  }

  // ── Chai, if we know the habit ──────────────────────────────────────
  const diet = String(fact(facts, 'diet_habits') ?? '');
  if (/chai|tea|چائے/i.test(diet) && /sugar|چینی|\d/.test(diet)) {
    out.push({
      category: 'food',
      weight: 70,
      becauseEn: `You told me: ${diet}. That is often the largest hidden source of sugar in the day.`,
      becauseUr: 'آپ نے بتایا تھا کہ دن میں کئی بار چینی والی چائے پیتی ہیں۔ یہ اکثر دن بھر کی سب سے بڑی چھپی ہوئی چینی ہوتی ہے۔',
      doEn: 'Drop one spoon of sugar per cup this week, and the second spoon next week. Going slowly is what makes it stick.',
      doUr: 'اس ہفتے ہر کپ میں ایک چمچ چینی کم کریں، اگلے ہفتے دوسرا۔ آہستہ کرنے سے ہی عادت بنتی ہے۔',
    });
  }

  // ── Roti portion, if we know it ─────────────────────────────────────
  const roti = Number(fact(facts, 'roti_per_meal'));
  if (Number.isFinite(roti) && roti >= 3) {
    out.push({
      category: 'food',
      weight: 68,
      becauseEn: `You eat about ${roti} rotis per meal. Each one is roughly 15–20 g of carbohydrate.`,
      becauseUr: `آپ ہر کھانے میں تقریباً ${roti} روٹیاں کھاتی ہیں۔ ہر روٹی میں پندرہ سے بیس گرام کاربوہائیڈریٹ ہوتا ہے۔`,
      doEn: `Reduce to ${roti - 1} and add an extra bowl of daal or sabzi so you are just as full.`,
      doUr: `${roti - 1} کریں اور ایک پیالی دال یا سبزی زیادہ لیں تاکہ پیٹ اتنا ہی بھرا رہے۔`,
    });
  }

  // ── Monitoring ──────────────────────────────────────────────────────
  if (f.daysSinceLastReading !== null && f.daysSinceLastReading >= 2) {
    out.push({
      category: 'monitoring',
      weight: 85,
      becauseEn: `Your last reading was ${f.daysSinceLastReading} days ago.`,
      becauseUr: `آپ کی آخری ریڈنگ ${f.daysSinceLastReading} دن پہلے تھی۔`,
      doEn: 'Check fasting sugar tomorrow morning before eating, and tell me the number.',
      doUr: 'کل صبح کھانے سے پہلے خالی پیٹ شوگر چیک کریں اور مجھے بتائیں۔',
    });
  } else if (f.timeInRange14 !== null && f.timeInRange14 < 70) {
    out.push({
      category: 'monitoring',
      weight: 60,
      becauseEn: `Only ${f.timeInRange14}% of your readings are in the healthy range (70–180).`,
      becauseUr: `آپ کی صرف ${f.timeInRange14} فیصد ریڈنگز صحت مند حد (ستر سے ایک سو اسی) میں ہیں۔`,
      doEn: 'Check twice on two days this week: fasting, and two hours after your biggest meal.',
      doUr: 'اس ہفتے دو دن دو بار چیک کریں: خالی پیٹ، اور سب سے بڑے کھانے کے دو گھنٹے بعد۔',
    });
  }

  // ── Feet — always, and first if it has ever been raised ─────────────
  out.push({
    category: 'feet',
    weight: 50,
    becauseEn: 'Foot wounds in diabetes worsen fast and are a leading cause of amputation in Pakistan.',
    becauseUr: 'ذیابیطس میں پاؤں کے زخم جلدی بگڑتے ہیں اور پاکستان میں ٹانگ کٹنے کی بڑی وجہ ہیں۔',
    doEn: 'Look at both feet every night, including between the toes. Never walk barefoot.',
    doUr: 'ہر رات دونوں پاؤں دیکھیں، انگلیوں کے درمیان بھی۔ کبھی ننگے پاؤں نہ چلیں۔',
  });

  // ── Doctor, when the trend genuinely warrants it ─────────────────────
  if ((f.mean7 !== null && f.mean7 > 180) || (f.timeInRange14 !== null && f.timeInRange14 < 50)) {
    out.push({
      category: 'doctor',
      weight: 78,
      becauseEn: `Your 7-day average is ${f.mean7} mg/dL. Diet and walking help, but an average this high usually needs your doctor to review the treatment.`,
      becauseUr: `آپ کا سات دن کا اوسط ${f.mean7} ہے۔ کھانے اور چہل قدمی سے فرق پڑتا ہے، مگر اتنے زیادہ اوسط پر ڈاکٹر کا علاج دیکھنا ضروری ہے۔`,
      doEn: 'Book a doctor visit this month and take your readings with you — write them down or show them this app.',
      doUr: 'اس مہینے ڈاکٹر سے وقت لیں اور اپنی ریڈنگز ساتھ لے جائیں — لکھ لیں یا یہ ایپ دکھا دیں۔',
    });
  }

  return out.sort((a, b) => b.weight - a.weight);
}

/** The plan as spoken text — top N actions, in the patient's language. */
export function planToText(actions: PlanAction[], lang: 'ur' | 'en', limit = 4): string {
  const top = actions.slice(0, limit);
  if (!top.length) {
    return lang === 'en'
      ? 'I do not have enough readings yet to make a plan. Tell me your sugar for a few days and I will build one.'
      : 'ابھی منصوبہ بنانے کے لیے کافی ریڈنگز نہیں ہیں۔ چند دن اپنی شوگر بتائیں تو میں بنا دوں گی۔';
  }
  const head = lang === 'en'
    ? 'Here is your plan for this week, based on your own readings:'
    : 'آپ کی اپنی ریڈنگز کے مطابق اس ہفتے کا منصوبہ:';
  const lines = top.map((a, i) => {
    const n = i + 1;
    return lang === 'en' ? `${n}. ${a.doEn} (${a.becauseEn})` : `${n}۔ ${a.doUr} (${a.becauseUr})`;
  });
  return [head, ...lines].join('\n');
}
